using System;using System.IO;using System.IO.Pipes;using System.Text;using System.Diagnostics;using System.Threading;using BuildX.PipePrototype;
class OwnerPeer {
 static void C(bool c,string s){if(!c)throw new Exception(s);Console.WriteLine("PASS "+s);}
 static void Main(string[] a){if(a[0]=="bystander"){Thread.Sleep(10000);return;}if(a[0]=="child"){if(Path.GetFileName(a[2]).StartsWith("hang")){Thread.Sleep(10000);return;}if(Path.GetFileName(a[2]).StartsWith("exit"))return;if(Path.GetFileName(a[2]).StartsWith("slow"))Thread.Sleep(800);using(var f=new FileStream(a[2],FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var p=new NamedPipeClientStream(".","buildx-owner-"+a[1],PipeDirection.InOut)){p.Connect(5000);var w=new StreamWriter(p){AutoFlush=true};w.WriteLine(f.SafeFileHandle.DangerousGetHandle().ToInt64().ToString("X"));p.ReadByte();}return;}
 string root=a[0];Directory.CreateDirectory(root);string exe=Process.GetCurrentProcess().MainModule.FileName;
 foreach(string mode in new[]{"ok","slow-timeout","slow-cancel","exit","hang"}){string id=Guid.NewGuid().ToString("D"),p=Path.Combine(root,mode+".json");File.WriteAllText(p,"{\"request_id\":\""+id+"\"}");var owner=new SpawnedPipeOwner(exe,p,id);using(var cancel=new ManualResetEvent(mode=="slow-cancel")){string state=owner.Wait(mode=="ok"?5000:100,cancel);C(owner.OriginalRequestId==id,"original request retained "+mode);C(state==(mode=="ok"?"observed":"unknown"),"bounded wait "+mode);if(mode.StartsWith("slow")){Thread.Sleep(1200);C(owner.Inspect()=="observed"&&owner.ObservedBytes!=null,"read-only recovery without replay "+mode);}if(mode=="exit"){Thread.Sleep(500);C(owner.Inspect()=="unknown" && owner.IsFinished,"exit remains unknown and receiver stops");}if(mode=="hang"){using(var bystander=Process.Start(new ProcessStartInfo{FileName=exe,Arguments="bystander",UseShellExecute=false,CreateNoWindow=true})){Thread.Sleep(3000);C(owner.StopRequested,"hung child stop requested");C(owner.ExitConfirmed && owner.IsMonitorFinished && owner.IsFinished,"tracked child exit confirmed and receiver stopped");C(owner.Inspect()=="unknown" && owner.OriginalRequestId==id,"original outcome remains unknown");C(!bystander.HasExited,"unrelated child unaffected");bystander.Kill();bystander.WaitForExit();}}}}
 }
}
